// Verification harness for mss_models.dart.
//
// Parses REAL API output (_fixtures.json, generated by catalog/mss_api.py)
// and MSS_ANTIGRAVITY_HANDOFF/examples/*.json through models in
// frontend/lib/models/mss_models.dart.
//
// Run:  dart verify_models.dart

import 'dart:convert';
import 'dart:io';

import '../../frontend/lib/models/mss_models.dart';

int _checks = 0;
int _failures = 0;

void check(bool condition, String label) {
  _checks++;
  if (condition) {
    print('  PASS  $label');
  } else {
    _failures++;
    print('  FAIL  $label');
  }
}

void main() {
  final raw = File('_fixtures.json').readAsStringSync();
  final f = jsonDecode(raw) as Map<String, dynamic>;

  print('\n=== search ===');
  final search = MssSearchResponse.fromJson(
      Map<String, dynamic>.from(f['search'] as Map));
  check(search.contractVersion.isNotEmpty, 'contractVersion parsed');
  check(search.catalogVersion != null, 'catalogVersion parsed');
  check(search.results.isNotEmpty, 'results parsed (${search.results.length})');
  check(search.queryText.contains('textile'), 'query text parsed');
  check(search.detectedIntent.intents.contains('LOAN_REQUEST'),
      'detected intent LOAN_REQUEST');
  check(search.detectedIntent.industries.contains('textile'),
      'detected industry textile');
  check(search.profileApplied.isNotEmpty, 'profileApplied echoed back');

  final top = search.results.first;
  check(top.rank == 1, 'rank parsed');
  check(top.schemeId.startsWith('SCH'), 'schemeId parsed (${top.schemeId})');
  check(top.score > 0, 'score parsed (${top.score})');
  check(top.matchReasons.isNotEmpty, 'matchReasons parsed');
  check(top.explanation.isNotEmpty, 'explanation parsed');
  check(top.confidence != null, 'confidence parsed');
  check(top.confidence!.level != ConfidenceLevel.unrecognised,
      'confidence level recognised (${top.confidence!.level.name})');
  check(top.rankingSignals.components.isNotEmpty, 'ranking components parsed');
  check(top.rankingSignals.weights.isNotEmpty, 'ranking weights parsed');
  check(top.applicability != null, 'applicability attached when profile sent');
  check(top.nextActions.isNotEmpty, 'nextActions parsed');

  final drift = (top.rankingSignals.recomputedScore - top.score).abs();
  check(drift < 0.01,
      'score reconstructible from components x weights (drift ${drift.toStringAsFixed(5)})');

  print('\n=== round-trip (offline cache) ===');
  final rt = MssSearchResponse.fromJson(
      jsonDecode(jsonEncode(search.toJson())) as Map<String, dynamic>);
  check(rt.results.length == search.results.length, 'result count survives');
  check(rt.results.first.schemeId == top.schemeId, 'schemeId survives');
  check(rt.results.first.score == top.score, 'score survives');
  check(rt.results.first.explanation == top.explanation, 'explanation survives');
  check(rt.detectedIntent.industries.join(',') ==
      search.detectedIntent.industries.join(','), 'intent survives');
  check(rt.results.first.nextActions.length == top.nextActions.length,
      'nextActions survive');

  print('\n=== backward compatibility ===');
  final withUnknown = Map<String, dynamic>.from(f['search'] as Map)
    ..['brandNewServerField'] = {'nested': true}
    ..['results'] = [
      {'schemeId': 'SCH000999', 'futureField': 42}
    ];
  final tolerated = MssSearchResponse.fromJson(withUnknown);
  check(tolerated.results.length == 1, 'unknown top-level field ignored');
  check(tolerated.results.first.schemeId == 'SCH000999',
      'result with only schemeId parses');
  check(tolerated.results.first.name == '', 'missing name defaults, no throw');
  check(tolerated.results.first.confidence == null,
      'missing confidence stays null');

  final emptyResp = MssSearchResponse.fromJson(<String, dynamic>{});
  check(emptyResp.results.isEmpty, 'entirely empty object parses');

  check(schemeStatusFrom('some_future_status') == SchemeStatus.unrecognised,
      'unknown scheme status degrades safely');
  check(confidenceLevelFrom('ultra') == ConfidenceLevel.unrecognised,
      'unknown confidence level degrades safely');

  print('\n=== warnings (zero-coverage filter) ===');
  final warned = MssSearchResponse.fromJson(
      Map<String, dynamic>.from(f['search_warn'] as Map));
  check(warned.warnings.isNotEmpty, 'warning surfaced');
  check(warned.warnings.first.code == 'FILTER_NO_COVERAGE',
      'warning code correct (${warned.warnings.first.code})');
  check(warned.warnings.first.hint != null, 'warning hint present');

  print('\n=== applicability ===');
  final app = MssApplicabilityResponse.fromJson(
      Map<String, dynamic>.from(f['applicability'] as Map));
  check(app.results.isNotEmpty, 'applicability results parsed');
  check(app.results.first.matchedFacets.isNotEmpty, 'matchedFacets parsed');
  check(app.profile.isNotEmpty, 'profile echoed');
  check(app.eligibleOnly.length <= app.results.length, 'eligibleOnly filter works');

  print('\n=== scheme detail ===');
  final detail = MssSchemeIntelligence.fromJson(
      Map<String, dynamic>.from(f['scheme_detail'] as Map));
  check(detail.schemeId == 'SCH000001', 'schemeId parsed');
  check(detail.name != null, 'name parsed');
  check(detail.finance.isNotEmpty, 'finance refs parsed');
  check(detail.authority.isNotEmpty, 'authority refs parsed');
  check(detail.applicability.isNotEmpty, 'applicability block parsed');
  check(detail.missingReferences.isEmpty, 'no missing references');
  check(detail.treds.isEmpty, 'treds legitimately empty (not an error)');

  print('\n=== closed scheme (highest-stakes rule) ===');
  final closed = MssSchemeIntelligence.fromJson(
      Map<String, dynamic>.from(f['scheme_detail_closed'] as Map));
  check(closed.schemeStatus == SchemeStatus.closed, 'status parsed as closed');
  final applyActions =
      closed.nextActions.where((a) => a.action == 'apply_online').toList();
  check(applyActions.isEmpty, 'NO apply action on a closed scheme');
  check(closed.nextActions.any((a) => a.isClosedMarker),
      'explicit closed marker present');

  print('\n=== Real Handoff Payload: scheme_details_response.json ===');
  final detailsFile = File('../../MSS_ANTIGRAVITY_HANDOFF/examples/scheme_details_response.json');
  if (detailsFile.existsSync()) {
    final detailsJson = jsonDecode(detailsFile.readAsStringSync()) as Map<String, dynamic>;
    final realDetail = MssSchemeIntelligence.fromJson(detailsJson);
    check(realDetail.schemeId == 'SCH000021', 'real scheme_details_response.json schemeId SCH000021 parsed');
    check(realDetail.finance.isNotEmpty, 'real finance refs parsed (${realDetail.finance.length})');
  }

  print('\n=== Real Handoff Payload: error_response.json ===');
  final errFile = File('../../MSS_ANTIGRAVITY_HANDOFF/examples/error_response.json');
  if (errFile.existsSync()) {
    final errJson = jsonDecode(errFile.readAsStringSync()) as Map<String, dynamic>;
    check(MssApiError.isError(errJson), 'real error_response.json detected');
    final realErr = MssApiError.fromJson(errJson);
    check(realErr.code == 'INVALID_REQUEST', 'real error code parsed (${realErr.code})');
  }

  print('\n=== meta ===');
  final meta = MssMeta.fromJson(Map<String, dynamic>.from(f['meta'] as Map));
  check(meta.catalogVersion != null, 'catalogVersion parsed');
  check(meta.catalogChecksum != null, 'catalogChecksum parsed');
  check(meta.entityCounts['scheme'] == 217, 'scheme count 217');
  check(meta.isStaleAgainst('some-old-tag'), 'stale detection positive');
  check(!meta.isStaleAgainst(meta.catalogVersion), 'stale detection negative');
  check(meta.zeroCoverageDimensions.contains('community'),
      'zero-coverage dimensions reported (${meta.zeroCoverageDimensions})');

  print('\n=== error ===');
  final errJson = Map<String, dynamic>.from(f['error'] as Map);
  check(MssApiError.isError(errJson), 'error detected via contract field');
  final err = MssApiError.fromJson(errJson);
  check(err.code == 'INVALID_REQUEST', 'error code parsed (${err.code})');
  check(err.field != null, 'error field attributed (${err.field})');
  check(!err.isRetryable, 'INVALID_REQUEST is not retryable');

  print('\n${'=' * 60}');
  print('$_checks checks, $_failures failure(s)');
  print('=' * 60);
  if (_failures > 0) exit(1);
}
